    public static func defaultSource(task: ModuleCompositionLearningTask) throws -> CompositeProjectDocument {
        var source = try preparedSource(task: task)
        source.root.edges = []
        for index in source.definitions.indices {
            source.definitions[index].body.edges = []
            if task == .orderName {
                source.definitions[index].composition = .init(kind:.graph,children:source.definitions[index].body.nodes.map {.init(localID:$0.id)})
            }
        }
        return source
    }
